CREATE TABLE `app_impact_zones` (`id` VARCHAR(191) NOT NULL, `slug` VARCHAR(96) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `targetPoints` INTEGER NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `sortOrder` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `app_impact_zones_slug_key`(`slug`), INDEX `app_impact_zones_active_sortOrder_idx`(`active`, `sortOrder`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_missions` (`id` VARCHAR(191) NOT NULL, `zoneId` VARCHAR(191) NOT NULL, `slug` VARCHAR(96) NOT NULL, `title` VARCHAR(191) NOT NULL, `summary` VARCHAR(500) NOT NULL, `problemDescription` TEXT NOT NULL, `objective` TEXT NOT NULL, `instructions` TEXT NOT NULL, `deliverables` JSON NOT NULL, `validationCriteria` JSON NOT NULL, `safetyNotes` TEXT NOT NULL, `difficulty` VARCHAR(32) NOT NULL, `estimatedMinutes` INTEGER NOT NULL, `points` INTEGER NOT NULL, `evidenceType` VARCHAR(64) NOT NULL, `participationMode` VARCHAR(32) NOT NULL, `publicationStatus` VARCHAR(32) NOT NULL DEFAULT 'DRAFT', `active` BOOLEAN NOT NULL DEFAULT true, `startsAt` DATETIME(3) NULL, `endsAt` DATETIME(3) NULL, `sortOrder` INTEGER NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `app_impact_missions_slug_key`(`slug`), INDEX `app_impact_missions_zoneId_publicationStatus_active_idx`(`zoneId`, `publicationStatus`, `active`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_capabilities` (`id` VARCHAR(191) NOT NULL, `slug` VARCHAR(96) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `category` VARCHAR(64) NOT NULL, `active` BOOLEAN NOT NULL DEFAULT true, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `app_impact_capabilities_slug_key`(`slug`), INDEX `app_impact_capabilities_active_category_idx`(`active`, `category`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_mission_capabilities` (`missionId` VARCHAR(191) NOT NULL, `capabilityId` VARCHAR(191) NOT NULL, `weight` INTEGER NOT NULL, INDEX `app_impact_mission_capabilities_capabilityId_idx`(`capabilityId`), PRIMARY KEY (`missionId`, `capabilityId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_participations` (`id` VARCHAR(191) NOT NULL, `missionId` VARCHAR(191) NOT NULL, `userId` VARCHAR(191) NOT NULL, `status` VARCHAR(32) NOT NULL DEFAULT 'ACTIVE', `revision` INTEGER NOT NULL DEFAULT 0, `startedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `completedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `app_impact_participations_userId_missionId_key`(`userId`, `missionId`), INDEX `app_impact_participations_userId_updatedAt_idx`(`userId`, `updatedAt`), INDEX `app_impact_participations_missionId_status_idx`(`missionId`, `status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_contributions` (`id` VARCHAR(191) NOT NULL, `participationId` VARCHAR(191) NOT NULL, `title` VARCHAR(191) NOT NULL, `description` TEXT NOT NULL, `processNotes` TEXT NULL, `resultUrl` VARCHAR(500) NULL, `repositoryUrl` VARCHAR(500) NULL, `reflection` TEXT NULL, `status` VARCHAR(32) NOT NULL DEFAULT 'DRAFT', `revision` INTEGER NOT NULL DEFAULT 0, `visibility` VARCHAR(32) NOT NULL DEFAULT 'PRIVATE', `publicAuthorizedAt` DATETIME(3) NULL, `publicAuthorizedById` VARCHAR(191) NULL, `reviewerId` VARCHAR(191) NULL, `reviewerEmailSnapshot` VARCHAR(191) NULL, `reviewerFeedback` TEXT NULL, `submittedAt` DATETIME(3) NULL, `reviewedAt` DATETIME(3) NULL, `approvedAt` DATETIME(3) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, UNIQUE INDEX `app_impact_contributions_participationId_key`(`participationId`), INDEX `app_impact_contributions_status_updatedAt_idx`(`status`, `updatedAt`), INDEX `app_impact_contributions_reviewerId_status_idx`(`reviewerId`, `status`), INDEX `app_impact_contributions_id_revision_status_idx`(`id`, `revision`, `status`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_contribution_files` (`id` VARCHAR(191) NOT NULL, `contributionId` VARCHAR(191) NOT NULL, `originalName` VARCHAR(255) NOT NULL, `storageKey` VARCHAR(255) NOT NULL, `mimeType` VARCHAR(127) NOT NULL, `fileSize` BIGINT UNSIGNED NOT NULL, `visibility` VARCHAR(32) NOT NULL DEFAULT 'PRIVATE', `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `app_impact_contribution_files_storageKey_key`(`storageKey`), INDEX `app_impact_contribution_files_contributionId_createdAt_idx`(`contributionId`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_career_capabilities` (`capabilityId` VARCHAR(191) NOT NULL, `canonicalProgramKey` VARCHAR(191) NOT NULL, `weight` INTEGER NOT NULL, INDEX `app_impact_career_capabilities_canonicalProgramKey_idx`(`canonicalProgramKey`), PRIMARY KEY (`capabilityId`, `canonicalProgramKey`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_zone_events` (`id` VARCHAR(191) NOT NULL, `zoneId` VARCHAR(191) NOT NULL, `contributionId` VARCHAR(191) NOT NULL, `eventType` VARCHAR(64) NOT NULL, `points` INTEGER NOT NULL, `description` VARCHAR(500) NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE INDEX `app_impact_zone_events_contributionId_eventType_key`(`contributionId`, `eventType`), INDEX `app_impact_zone_events_zoneId_createdAt_idx`(`zoneId`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `app_impact_contribution_events` (`id` VARCHAR(191) NOT NULL, `contributionId` VARCHAR(191) NOT NULL, `actorUserId` VARCHAR(191) NULL, `actorEmailSnapshot` VARCHAR(191) NULL, `fromStatus` VARCHAR(32) NULL, `toStatus` VARCHAR(32) NOT NULL, `reason` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), INDEX `app_impact_contribution_events_contributionId_createdAt_idx`(`contributionId`, `createdAt`), INDEX `app_impact_contribution_events_actorUserId_createdAt_idx`(`actorUserId`, `createdAt`), PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `app_impact_missions` ADD CONSTRAINT `app_impact_missions_zoneId_fkey` FOREIGN KEY (`zoneId`) REFERENCES `app_impact_zones`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_mission_capabilities` ADD CONSTRAINT `app_impact_mission_capabilities_missionId_fkey` FOREIGN KEY (`missionId`) REFERENCES `app_impact_missions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_mission_capabilities_capabilityId_fkey` FOREIGN KEY (`capabilityId`) REFERENCES `app_impact_capabilities`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_participations` ADD CONSTRAINT `app_impact_participations_missionId_fkey` FOREIGN KEY (`missionId`) REFERENCES `app_impact_missions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_participations_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `app_users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_contributions` ADD CONSTRAINT `app_impact_contributions_participationId_fkey` FOREIGN KEY (`participationId`) REFERENCES `app_impact_participations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_contributions_publicAuthorizedById_fkey` FOREIGN KEY (`publicAuthorizedById`) REFERENCES `app_users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_contributions_reviewerId_fkey` FOREIGN KEY (`reviewerId`) REFERENCES `app_users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `app_impact_contribution_files` ADD CONSTRAINT `app_impact_contribution_files_contributionId_fkey` FOREIGN KEY (`contributionId`) REFERENCES `app_impact_contributions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_career_capabilities` ADD CONSTRAINT `app_impact_career_capabilities_capabilityId_fkey` FOREIGN KEY (`capabilityId`) REFERENCES `app_impact_capabilities`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_zone_events` ADD CONSTRAINT `app_impact_zone_events_zoneId_fkey` FOREIGN KEY (`zoneId`) REFERENCES `app_impact_zones`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_zone_events_contributionId_fkey` FOREIGN KEY (`contributionId`) REFERENCES `app_impact_contributions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `app_impact_contribution_events` ADD CONSTRAINT `app_impact_contribution_events_contributionId_fkey` FOREIGN KEY (`contributionId`) REFERENCES `app_impact_contributions`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, ADD CONSTRAINT `app_impact_contribution_events_actorUserId_fkey` FOREIGN KEY (`actorUserId`) REFERENCES `app_users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `app_impact_zones` ADD CONSTRAINT `app_impact_zones_targetPoints_check` CHECK (`targetPoints` > 0);
ALTER TABLE `app_impact_missions` ADD CONSTRAINT `app_impact_missions_points_check` CHECK (`points` > 0), ADD CONSTRAINT `app_impact_missions_estimatedMinutes_check` CHECK (`estimatedMinutes` > 0);
ALTER TABLE `app_impact_mission_capabilities` ADD CONSTRAINT `app_impact_mission_capabilities_weight_check` CHECK (`weight` BETWEEN 1 AND 5);
ALTER TABLE `app_impact_career_capabilities` ADD CONSTRAINT `app_impact_career_capabilities_weight_check` CHECK (`weight` BETWEEN 1 AND 5);
